-- =====================================================================
-- DML CONTABILIDADE LTDA - Sistema de Gestão de Informações
-- Modelo lógico (conversão do DER conceitual) - Script para MySQL 8.0.16+
--   * 30 tabelas: 25 originais + 5 para compras/contas a pagar
--   * Chaves estrangeiras com ON DELETE RESTRICT / ON UPDATE RESTRICT
--     (dados contábeis não são apagados: usar a coluna status).
--   * CHECK só é aplicado a partir do MySQL 8.0.16.
-- Convenção: competencia = 'AAAA-MM' (ex.: '2026-11').
-- =====================================================================

DROP DATABASE IF EXISTS dml_contabilidade;
CREATE DATABASE dml_contabilidade
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dml_contabilidade;

-- ---------------------------------------------------------------------
-- 1. Tabelas independentes (sem chave estrangeira)
-- ---------------------------------------------------------------------

CREATE TABLE departamento (
  id_departamento INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome            VARCHAR(80)  NOT NULL,
  descricao       VARCHAR(255) NULL,
  CONSTRAINT pk_departamento      PRIMARY KEY (id_departamento),
  CONSTRAINT uq_departamento_nome UNIQUE (nome)
) ENGINE=InnoDB;

CREATE TABLE cliente (
  id_cliente        INT UNSIGNED NOT NULL AUTO_INCREMENT,
  codigo_cliente    VARCHAR(20)  NOT NULL,
  nome_razao_social VARCHAR(150) NOT NULL,
  tipo_cliente      CHAR(2)      NOT NULL,
  documento_fiscal  VARCHAR(14)  NOT NULL,          -- somente dígitos
  regime_tributario VARCHAR(20)  NULL,
  status            VARCHAR(10)  NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT pk_cliente        PRIMARY KEY (id_cliente),
  CONSTRAINT uq_cliente_codigo UNIQUE (codigo_cliente),
  CONSTRAINT uq_cliente_doc    UNIQUE (documento_fiscal),
  CONSTRAINT ck_cliente_tipo   CHECK (tipo_cliente IN ('PF','PJ')),
  CONSTRAINT ck_cliente_doc    CHECK (documento_fiscal REGEXP '^[0-9]+$'
                                 AND ((tipo_cliente = 'PF' AND CHAR_LENGTH(documento_fiscal) = 11)
                                   OR (tipo_cliente = 'PJ' AND CHAR_LENGTH(documento_fiscal) = 14))),
  CONSTRAINT ck_cliente_regime CHECK (regime_tributario IN
                                 ('MEI','SIMPLES_NACIONAL','LUCRO_PRESUMIDO','LUCRO_REAL','ISENTO')),
  CONSTRAINT ck_cliente_status CHECK (status IN ('ATIVO','INATIVO','SUSPENSO'))
) ENGINE=InnoDB;

CREATE TABLE servico (
  id_servico          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome                VARCHAR(100) NOT NULL,
  descricao           VARCHAR(255) NULL,
  periodicidade_padrao VARCHAR(12) NOT NULL DEFAULT 'MENSAL',
  status              VARCHAR(10)  NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT pk_servico        PRIMARY KEY (id_servico),
  CONSTRAINT uq_servico_nome   UNIQUE (nome),
  CONSTRAINT ck_servico_period CHECK (periodicidade_padrao IN
                               ('UNICA','MENSAL','BIMESTRAL','TRIMESTRAL','SEMESTRAL','ANUAL')),
  CONSTRAINT ck_servico_status CHECK (status IN ('ATIVO','INATIVO'))
) ENGINE=InnoDB;

CREATE TABLE tipo_documento (
  id_tipo_documento INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome              VARCHAR(100) NOT NULL,
  descricao         VARCHAR(255) NULL,
  CONSTRAINT pk_tipo_documento      PRIMARY KEY (id_tipo_documento),
  CONSTRAINT uq_tipo_documento_nome UNIQUE (nome)
) ENGINE=InnoDB;

CREATE TABLE tipo_obrigacao (
  id_tipo_obrigacao INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome              VARCHAR(100) NOT NULL,
  descricao         VARCHAR(255) NULL,
  periodicidade     VARCHAR(12)  NOT NULL,
  base_legal        VARCHAR(255) NULL,
  pode_gerar_multa  BOOLEAN      NOT NULL DEFAULT FALSE,
  CONSTRAINT pk_tipo_obrigacao        PRIMARY KEY (id_tipo_obrigacao),
  CONSTRAINT uq_tipo_obrigacao_nome   UNIQUE (nome),
  CONSTRAINT ck_tipo_obrigacao_period CHECK (periodicidade IN
                                      ('MENSAL','TRIMESTRAL','SEMESTRAL','ANUAL','EVENTUAL')),
  CONSTRAINT ck_tipo_obrigacao_multa  CHECK (pode_gerar_multa IN (0,1))
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 2. Tabelas dependentes (relacionamentos 1:N -> FK no lado "N")
-- ---------------------------------------------------------------------

CREATE TABLE funcionario (                       -- LOTA (1:N)
  id_funcionario  INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_departamento INT UNSIGNED NOT NULL,
  nome            VARCHAR(120) NOT NULL,
  cargo           VARCHAR(80)  NOT NULL,
  login           VARCHAR(50)  NOT NULL,
  status          VARCHAR(10)  NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT pk_funcionario        PRIMARY KEY (id_funcionario),
  CONSTRAINT uq_funcionario_login  UNIQUE (login),
  CONSTRAINT ck_funcionario_status CHECK (status IN ('ATIVO','INATIVO')),
  CONSTRAINT fk_funcionario_departamento FOREIGN KEY (id_departamento)
    REFERENCES departamento (id_departamento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE contato (                           -- POSSUI (1:N)
  id_contato INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_cliente INT UNSIGNED NOT NULL,
  tipo       VARCHAR(10)  NOT NULL,
  valor      VARCHAR(150) NOT NULL,
  principal  BOOLEAN      NOT NULL DEFAULT FALSE,
  CONSTRAINT pk_contato           PRIMARY KEY (id_contato),
  CONSTRAINT uq_contato_cli_valor UNIQUE (id_cliente, tipo, valor),
  CONSTRAINT ck_contato_tipo      CHECK (tipo IN ('EMAIL','TELEFONE','CELULAR','WHATSAPP')),
  CONSTRAINT ck_contato_principal CHECK (principal IN (0,1)),
  CONSTRAINT fk_contato_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE certificado_digital (               -- MANTÉM (1:N)
  id_certificado INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_cliente     INT UNSIGNED NOT NULL,
  tipo           VARCHAR(10)  NOT NULL,
  data_emissao   DATE         NOT NULL,
  data_validade  DATE         NOT NULL,
  status         VARCHAR(10)  NOT NULL DEFAULT 'ATIVO',
  data_aviso_renovacao DATE NULL,
  data_solicitacao_renovacao DATE NULL,
  status_renovacao VARCHAR(20) NULL,
  CONSTRAINT ck_certificado_renovacao CHECK (status_renovacao IS NULL OR status_renovacao IN ('NAO_INICIADA','SOLICITADA','EM_ANDAMENTO','CONCLUIDA')),
  CONSTRAINT pk_certificado_digital PRIMARY KEY (id_certificado),
  CONSTRAINT ck_certificado_tipo    CHECK (tipo IN ('A1','A3','NUVEM')),
  CONSTRAINT ck_certificado_datas   CHECK (data_validade > data_emissao),
  CONSTRAINT ck_certificado_status  CHECK (status IN ('ATIVO','VENCIDO','REVOGADO')),
  CONSTRAINT fk_certificado_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE contrato (                          -- POSSUI (1:N)
  id_contrato          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_cliente           INT UNSIGNED NOT NULL,
  data_inicio          DATE         NOT NULL,
  data_fim             DATE         NULL,
  data_encerramento    DATE         NULL,
  destino_documentacao VARCHAR(255) NULL,
  status               VARCHAR(10)  NOT NULL DEFAULT 'ATIVO',
  motivo_encerramento VARCHAR(255) NULL,
  solicitante_encerramento VARCHAR(15) NULL,
  data_solicitacao_encerramento DATE NULL,
  data_entrega_documentacao DATE NULL,
  meio_entrega_documentacao VARCHAR(20) NULL,
  CONSTRAINT ck_contrato_solicitante CHECK (solicitante_encerramento IS NULL OR solicitante_encerramento IN ('CLIENTE','ESCRITORIO')),
  CONSTRAINT ck_contrato_meio_entrega CHECK (meio_entrega_documentacao IS NULL OR meio_entrega_documentacao IN ('EMAIL','MOTOFRETE','RETIRADA')),
  CONSTRAINT ck_contrato_datas_entrega CHECK (data_entrega_documentacao IS NULL OR data_encerramento IS NULL OR data_entrega_documentacao >= data_encerramento),
  CONSTRAINT pk_contrato        PRIMARY KEY (id_contrato),
  CONSTRAINT ck_contrato_status CHECK (status IN ('ATIVO','SUSPENSO','ENCERRADO')),
  CONSTRAINT ck_contrato_fim    CHECK (data_fim IS NULL OR data_fim >= data_inicio),
  CONSTRAINT ck_contrato_encerr CHECK (data_encerramento IS NULL OR data_encerramento >= data_inicio),
  CONSTRAINT ck_contrato_status_encerr CHECK (status <> 'ENCERRADO' OR data_encerramento IS NOT NULL),
  CONSTRAINT fk_contrato_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE fatura (                            -- GERA (1:N)
  id_fatura       INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  id_contrato     INT UNSIGNED  NOT NULL,
  competencia     CHAR(7)       NOT NULL,
  valor_total     DECIMAL(12,2) NOT NULL,
  data_vencimento DATE          NOT NULL,
  status          VARCHAR(20)   NOT NULL DEFAULT 'ABERTA',
  CONSTRAINT pk_fatura          PRIMARY KEY (id_fatura),
  CONSTRAINT uq_fatura_contr_comp UNIQUE (id_contrato, competencia),
  CONSTRAINT ck_fatura_comp     CHECK (competencia REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_fatura_valor    CHECK (valor_total >= 0),
  CONSTRAINT ck_fatura_status   CHECK (status IN
                                ('ABERTA','PARCIALMENTE_PAGA','PAGA','VENCIDA','CANCELADA')),
  CONSTRAINT fk_fatura_contrato FOREIGN KEY (id_contrato)
    REFERENCES contrato (id_contrato) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE pagamento (                         -- QUITA (1:N)
  id_pagamento    INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  id_fatura       INT UNSIGNED  NOT NULL,
  valor_pago      DECIMAL(12,2) NOT NULL,
  data_pagamento  DATE          NOT NULL,
  forma_pagamento VARCHAR(15)   NOT NULL,
  status          VARCHAR(12)   NOT NULL DEFAULT 'CONFIRMADO',
  CONSTRAINT pk_pagamento        PRIMARY KEY (id_pagamento),
  CONSTRAINT ck_pagamento_valor  CHECK (valor_pago > 0),
  CONSTRAINT ck_pagamento_forma  CHECK (forma_pagamento IN
                                 ('PIX','BOLETO','TRANSFERENCIA','CARTAO','DINHEIRO')),
  CONSTRAINT ck_pagamento_status CHECK (status IN ('PENDENTE','CONFIRMADO','ESTORNADO')),
  CONSTRAINT fk_pagamento_fatura FOREIGN KEY (id_fatura)
    REFERENCES fatura (id_fatura) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE documento (                         -- FORNECE e CLASSIFICA (1:N)
  id_documento      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_cliente        INT UNSIGNED NOT NULL,
  id_tipo_documento INT UNSIGNED NOT NULL,
  descricao         VARCHAR(255) NULL,
  competencia       CHAR(7)      NULL,
  data_recebimento  DATE         NOT NULL DEFAULT (CURRENT_DATE),
  meio_recebimento  VARCHAR(12)  NOT NULL,
  data_conferencia  DATE         NULL,
  status            VARCHAR(15)  NOT NULL DEFAULT 'RECEBIDO',
  CONSTRAINT pk_documento        PRIMARY KEY (id_documento),
  CONSTRAINT ck_documento_comp   CHECK (competencia IS NULL
                                 OR competencia REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_documento_meio   CHECK (meio_recebimento IN
                                 ('EMAIL','WHATSAPP','PRESENCIAL','PORTAL','CORREIOS')),
  CONSTRAINT ck_documento_conf   CHECK (data_conferencia IS NULL OR data_conferencia >= data_recebimento),
  CONSTRAINT ck_documento_status CHECK (status IN
                                 ('RECEBIDO','EM_CONFERENCIA','CONFERIDO','REJEITADO')),
  CONSTRAINT fk_documento_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_documento_tipo FOREIGN KEY (id_tipo_documento)
    REFERENCES tipo_documento (id_tipo_documento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE execucao_servico (                  -- GERA (contrato) e REFERE_A (serviço) (1:N)
  id_execucao   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_contrato   INT UNSIGNED NOT NULL,
  id_servico    INT UNSIGNED NOT NULL,
  competencia   CHAR(7)      NOT NULL,
  data_inicio   DATE         NULL,
  prazo         DATE         NOT NULL,
  data_conclusao DATE        NULL,
  status        VARCHAR(15)  NOT NULL DEFAULT 'PENDENTE',
  CONSTRAINT pk_execucao_servico   PRIMARY KEY (id_execucao),
  CONSTRAINT uq_execucao_ctr_srv_comp UNIQUE (id_contrato, id_servico, competencia),
  CONSTRAINT ck_execucao_comp      CHECK (competencia REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_execucao_datas     CHECK (data_conclusao IS NULL OR data_inicio IS NULL
                                   OR data_conclusao >= data_inicio),
  CONSTRAINT ck_execucao_status    CHECK (status IN
                                   ('PENDENTE','EM_ANDAMENTO','EM_REVISAO','CONCLUIDA','CANCELADA')),
  CONSTRAINT ck_execucao_concl     CHECK (status <> 'CONCLUIDA' OR data_conclusao IS NOT NULL),
  CONSTRAINT fk_execucao_contrato FOREIGN KEY (id_contrato)
    REFERENCES contrato (id_contrato) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_execucao_servico FOREIGN KEY (id_servico)
    REFERENCES servico (id_servico) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE tarefa (                            -- GERA (1:N)
  id_tarefa      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_execucao    INT UNSIGNED NOT NULL,
  descricao      VARCHAR(255) NOT NULL,
  data_inicio    DATE         NULL,
  prazo          DATE         NOT NULL,
  data_conclusao DATE         NULL,
  status         VARCHAR(15)  NOT NULL DEFAULT 'PENDENTE',
  CONSTRAINT pk_tarefa        PRIMARY KEY (id_tarefa),
  CONSTRAINT ck_tarefa_datas  CHECK (data_conclusao IS NULL OR data_inicio IS NULL
                              OR data_conclusao >= data_inicio),
  CONSTRAINT ck_tarefa_status CHECK (status IN
                              ('PENDENTE','EM_ANDAMENTO','CONCLUIDA','CANCELADA')),
  CONSTRAINT ck_tarefa_concl  CHECK (status <> 'CONCLUIDA' OR data_conclusao IS NOT NULL),
  CONSTRAINT fk_tarefa_execucao FOREIGN KEY (id_execucao)
    REFERENCES execucao_servico (id_execucao) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE revisao_execucao (                  -- RECEBE e REALIZA (1:N)
  id_revisao_exec INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_execucao     INT UNSIGNED NOT NULL,
  id_funcionario  INT UNSIGNED NOT NULL,
  data_revisao    DATE         NOT NULL DEFAULT (CURRENT_DATE),
  resultado       VARCHAR(25)  NOT NULL,
  observacao      TEXT         NULL,
  CONSTRAINT pk_revisao_execucao       PRIMARY KEY (id_revisao_exec),
  CONSTRAINT ck_revisao_exec_resultado CHECK (resultado IN
                                       ('APROVADA','APROVADA_COM_RESSALVAS','REPROVADA')),
  CONSTRAINT ck_revisao_exec_obs       CHECK (resultado = 'APROVADA' OR observacao IS NOT NULL),
  CONSTRAINT fk_revisao_exec_execucao FOREIGN KEY (id_execucao)
    REFERENCES execucao_servico (id_execucao) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_revisao_exec_funcionario FOREIGN KEY (id_funcionario)
    REFERENCES funcionario (id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE pendencia_documental (              -- ORIGINA (1:N) e REFERENTE_A (0,1 : N)
  id_pendencia       INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_execucao        INT UNSIGNED NOT NULL,
  id_tipo_documento  INT UNSIGNED NULL,          -- (0,1): pendência pode não ter tipo
  tipo_pendencia     VARCHAR(25)  NOT NULL,
  competencia        CHAR(7)      NOT NULL,
  data_identificacao DATE         NOT NULL DEFAULT (CURRENT_DATE),
  data_comunicacao   DATE         NULL,
  canal_comunicacao  VARCHAR(12)  NULL,
  status             VARCHAR(12)  NOT NULL DEFAULT 'ABERTA',
  CONSTRAINT pk_pendencia_documental PRIMARY KEY (id_pendencia),
  CONSTRAINT ck_pendencia_tipo   CHECK (tipo_pendencia IN
                                 ('DOCUMENTO_AUSENTE','DOCUMENTO_ILEGIVEL',
                                  'DOCUMENTO_INCORRETO','INFORMACAO_INCOMPLETA')),
  CONSTRAINT ck_pendencia_comp   CHECK (competencia REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_pendencia_canal  CHECK (canal_comunicacao IN
                                 ('EMAIL','TELEFONE','WHATSAPP','PRESENCIAL')),
  CONSTRAINT ck_pendencia_comunic CHECK ((data_comunicacao IS NULL) = (canal_comunicacao IS NULL)),
  CONSTRAINT ck_pendencia_datas  CHECK (data_comunicacao IS NULL
                                 OR data_comunicacao >= data_identificacao),
  CONSTRAINT ck_pendencia_status CHECK (status IN
                                 ('ABERTA','COMUNICADA','RESOLVIDA','CANCELADA')),
  CONSTRAINT fk_pendencia_execucao FOREIGN KEY (id_execucao)
    REFERENCES execucao_servico (id_execucao) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_pendencia_tipo_doc FOREIGN KEY (id_tipo_documento)
    REFERENCES tipo_documento (id_tipo_documento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE obrigacao (                         -- POSSUI, CLASSIFICA, RESPONDE_POR (1:N)
  id_obrigacao      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_cliente        INT UNSIGNED NOT NULL,
  id_tipo_obrigacao INT UNSIGNED NOT NULL,
  id_departamento   INT UNSIGNED NOT NULL,
  competencia       CHAR(7)      NOT NULL,
  prazo             DATE         NOT NULL,
  data_conclusao    DATE         NULL,
  status            VARCHAR(15)  NOT NULL DEFAULT 'PENDENTE',
  CONSTRAINT pk_obrigacao        PRIMARY KEY (id_obrigacao),
  CONSTRAINT uq_obrigacao_cli_tipo_comp UNIQUE (id_cliente, id_tipo_obrigacao, competencia),
  CONSTRAINT ck_obrigacao_comp   CHECK (competencia REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  CONSTRAINT ck_obrigacao_status CHECK (status IN
                                 ('PENDENTE','EM_ANDAMENTO','ENTREGUE','ATRASADA','CANCELADA')),
  CONSTRAINT ck_obrigacao_concl  CHECK (status <> 'ENTREGUE' OR data_conclusao IS NOT NULL),
  CONSTRAINT fk_obrigacao_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_obrigacao_tipo FOREIGN KEY (id_tipo_obrigacao)
    REFERENCES tipo_obrigacao (id_tipo_obrigacao) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_obrigacao_departamento FOREIGN KEY (id_departamento)
    REFERENCES departamento (id_departamento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE revisao_obrigacao (                 -- RECEBE e REALIZA (1:N)
  id_revisao_obrig INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_obrigacao     INT UNSIGNED NOT NULL,
  id_funcionario   INT UNSIGNED NOT NULL,
  data_revisao     DATE         NOT NULL DEFAULT (CURRENT_DATE),
  resultado        VARCHAR(25)  NOT NULL,
  observacao       TEXT         NULL,
  CONSTRAINT pk_revisao_obrigacao        PRIMARY KEY (id_revisao_obrig),
  CONSTRAINT ck_revisao_obrig_resultado  CHECK (resultado IN
                                         ('APROVADA','APROVADA_COM_RESSALVAS','REPROVADA')),
  CONSTRAINT ck_revisao_obrig_obs        CHECK (resultado = 'APROVADA' OR observacao IS NOT NULL),
  CONSTRAINT fk_revisao_obrig_obrigacao FOREIGN KEY (id_obrigacao)
    REFERENCES obrigacao (id_obrigacao) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_revisao_obrig_funcionario FOREIGN KEY (id_funcionario)
    REFERENCES funcionario (id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE multa (                             -- ACARRETA (1:N)
  id_multa        INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  id_obrigacao    INT UNSIGNED  NOT NULL,
  valor           DECIMAL(12,2) NOT NULL,
  data_ocorrencia DATE          NOT NULL,
  motivo          VARCHAR(255)  NOT NULL,
  status          VARCHAR(12)   NOT NULL DEFAULT 'PENDENTE',
  CONSTRAINT pk_multa        PRIMARY KEY (id_multa),
  CONSTRAINT ck_multa_valor  CHECK (valor >= 0),
  CONSTRAINT ck_multa_status CHECK (status IN ('PENDENTE','PAGA','CONTESTADA','CANCELADA')),
  CONSTRAINT fk_multa_obrigacao FOREIGN KEY (id_obrigacao)
    REFERENCES obrigacao (id_obrigacao) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------
-- 3. Tabelas associativas (relacionamentos N:N, ternário e auto-relacionamento)
-- ---------------------------------------------------------------------

CREATE TABLE contrato_servico (                  -- INCLUI (N:N com atributos)
  id_contrato           INT UNSIGNED  NOT NULL,
  id_servico            INT UNSIGNED  NOT NULL,
  valor_acordado        DECIMAL(10,2) NOT NULL,
  periodicidade_acordada VARCHAR(12)  NOT NULL,
  dia_limite_envio      TINYINT UNSIGNED NULL,
  data_inicio           DATE          NOT NULL,
  data_fim              DATE          NULL,
  status                VARCHAR(10)   NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT pk_contrato_servico PRIMARY KEY (id_contrato, id_servico),
  CONSTRAINT ck_ctr_srv_valor    CHECK (valor_acordado >= 0),
  CONSTRAINT ck_ctr_srv_period   CHECK (periodicidade_acordada IN
                                 ('UNICA','MENSAL','BIMESTRAL','TRIMESTRAL','SEMESTRAL','ANUAL')),
  CONSTRAINT ck_ctr_srv_dia      CHECK (dia_limite_envio BETWEEN 1 AND 31),
  CONSTRAINT ck_ctr_srv_datas    CHECK (data_fim IS NULL OR data_fim >= data_inicio),
  CONSTRAINT ck_ctr_srv_status   CHECK (status IN ('ATIVO','SUSPENSO','ENCERRADO')),
  CONSTRAINT fk_ctr_srv_contrato FOREIGN KEY (id_contrato)
    REFERENCES contrato (id_contrato) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ctr_srv_servico FOREIGN KEY (id_servico)
    REFERENCES servico (id_servico) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE servico_tipo_documento (            -- EXIGE (N:N com atributos)
  id_servico        INT UNSIGNED NOT NULL,
  id_tipo_documento INT UNSIGNED NOT NULL,
  obrigatorio       BOOLEAN      NOT NULL DEFAULT TRUE,
  observacao        VARCHAR(255) NULL,
  CONSTRAINT pk_servico_tipo_documento PRIMARY KEY (id_servico, id_tipo_documento),
  CONSTRAINT ck_srv_tipodoc_obrig CHECK (obrigatorio IN (0,1)),
  CONSTRAINT fk_srv_tipodoc_servico FOREIGN KEY (id_servico)
    REFERENCES servico (id_servico) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_srv_tipodoc_tipo FOREIGN KEY (id_tipo_documento)
    REFERENCES tipo_documento (id_tipo_documento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE execucao_documento (                -- UTILIZA (N:N)
  id_execucao  INT UNSIGNED NOT NULL,
  id_documento INT UNSIGNED NOT NULL,
  CONSTRAINT pk_execucao_documento PRIMARY KEY (id_execucao, id_documento),
  CONSTRAINT fk_exec_doc_execucao FOREIGN KEY (id_execucao)
    REFERENCES execucao_servico (id_execucao) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_exec_doc_documento FOREIGN KEY (id_documento)
    REFERENCES documento (id_documento) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE tarefa_funcionario (                -- ASSUME (N:N com atributos)
  id_tarefa       INT UNSIGNED NOT NULL,
  id_funcionario  INT UNSIGNED NOT NULL,
  papel           VARCHAR(15)  NOT NULL DEFAULT 'EXECUTOR',
  data_atribuicao DATE         NOT NULL DEFAULT (CURRENT_DATE),
  CONSTRAINT pk_tarefa_funcionario PRIMARY KEY (id_tarefa, id_funcionario),
  CONSTRAINT ck_tarefa_func_papel  CHECK (papel IN ('RESPONSAVEL','EXECUTOR','REVISOR','APOIO')),
  CONSTRAINT fk_tarefa_func_tarefa FOREIGN KEY (id_tarefa)
    REFERENCES tarefa (id_tarefa) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_tarefa_func_funcionario FOREIGN KEY (id_funcionario)
    REFERENCES funcionario (id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE tarefa_dependencia (                -- DEPENDE_DE (auto-relacionamento N:N)
  id_tarefa_dependente   INT UNSIGNED NOT NULL,  -- papel "dependente"
  id_tarefa_pre_requisito INT UNSIGNED NOT NULL, -- papel "pré-requisito"
  CONSTRAINT pk_tarefa_dependencia PRIMARY KEY (id_tarefa_dependente, id_tarefa_pre_requisito),
  CONSTRAINT ck_tarefa_dep_distintas CHECK (id_tarefa_dependente <> id_tarefa_pre_requisito),
  CONSTRAINT fk_tarefa_dep_dependente FOREIGN KEY (id_tarefa_dependente)
    REFERENCES tarefa (id_tarefa) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_tarefa_dep_prerequisito FOREIGN KEY (id_tarefa_pre_requisito)
    REFERENCES tarefa (id_tarefa) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE responsabilidade (                  -- RESPONSABILIDADE (ternário N:N:N)
  id_cliente            INT UNSIGNED NOT NULL,
  id_departamento       INT UNSIGNED NOT NULL,
  id_funcionario        INT UNSIGNED NOT NULL,
  data_inicio           DATE         NOT NULL DEFAULT (CURRENT_DATE),
  tipo_responsabilidade VARCHAR(12)  NOT NULL,
  data_fim              DATE         NULL,
  CONSTRAINT pk_responsabilidade PRIMARY KEY (id_cliente, id_departamento, id_funcionario, data_inicio),
  CONSTRAINT ck_resp_tipo   CHECK (tipo_responsabilidade IN ('PRINCIPAL','SECUNDARIA','SUPERVISAO')),
  CONSTRAINT ck_resp_datas  CHECK (data_fim IS NULL OR data_fim >= data_inicio),
  CONSTRAINT fk_resp_cliente FOREIGN KEY (id_cliente)
    REFERENCES cliente (id_cliente) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_resp_departamento FOREIGN KEY (id_departamento)
    REFERENCES departamento (id_departamento) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_resp_funcionario FOREIGN KEY (id_funcionario)
    REFERENCES funcionario (id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;


-- ---------------------------------------------------------------------
-- 3B. Compras e contas a pagar (5 novas tabelas da revisao do DER)
-- ---------------------------------------------------------------------
CREATE TABLE fornecedor (
  id_fornecedor INT UNSIGNED NOT NULL AUTO_INCREMENT,
  nome_razao_social VARCHAR(150) NOT NULL,
  documento_fiscal VARCHAR(14) NOT NULL,
  tipo_fornecedor CHAR(2) NOT NULL,
  status VARCHAR(10) NOT NULL DEFAULT 'ATIVO',
  CONSTRAINT pk_fornecedor PRIMARY KEY (id_fornecedor),
  CONSTRAINT uq_fornecedor_doc UNIQUE (documento_fiscal),
  CONSTRAINT ck_fornecedor_tipo CHECK (tipo_fornecedor IN ('PF','PJ')),
  CONSTRAINT ck_fornecedor_documento CHECK (documento_fiscal REGEXP '^[0-9]+$' AND
     ((tipo_fornecedor='PF' AND CHAR_LENGTH(documento_fiscal)=11) OR
      (tipo_fornecedor='PJ' AND CHAR_LENGTH(documento_fiscal)=14))),
  CONSTRAINT ck_fornecedor_status CHECK (status IN ('ATIVO','INATIVO'))
) ENGINE=InnoDB;

CREATE TABLE solicitacao_compra (
  id_solicitacao INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_funcionario INT UNSIGNED NOT NULL,
  id_aprovador INT UNSIGNED NULL,
  data_solicitacao DATE NOT NULL,
  data_decisao DATE NULL,
  status VARCHAR(15) NOT NULL DEFAULT 'PENDENTE',
  observacao VARCHAR(255) NULL,
  CONSTRAINT pk_solicitacao_compra PRIMARY KEY (id_solicitacao),
  CONSTRAINT ck_sol_compra_status CHECK (status IN ('PENDENTE','APROVADA','REJEITADA','CANCELADA')),
  CONSTRAINT ck_sol_compra_decisao CHECK ((status NOT IN ('APROVADA','REJEITADA')) OR
    (id_aprovador IS NOT NULL AND data_decisao IS NOT NULL)),
  CONSTRAINT ck_sol_compra_datas CHECK (data_decisao IS NULL OR data_decisao>=data_solicitacao),
  CONSTRAINT fk_sol_compra_solicitante FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sol_compra_aprovador FOREIGN KEY (id_aprovador) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE item_compra (
  id_item_compra INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_solicitacao INT UNSIGNED NOT NULL,
  descricao VARCHAR(150) NOT NULL,
  quantidade DECIMAL(10,2) NOT NULL,
  valor_unitario DECIMAL(10,2) NOT NULL,
  CONSTRAINT pk_item_compra PRIMARY KEY (id_item_compra),
  CONSTRAINT ck_item_compra_quantidade CHECK (quantidade>0),
  CONSTRAINT ck_item_compra_valor CHECK (valor_unitario>=0),
  CONSTRAINT fk_item_compra_solicitacao FOREIGN KEY (id_solicitacao) REFERENCES solicitacao_compra(id_solicitacao) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE conta_pagar (
  id_conta_pagar INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_fornecedor INT UNSIGNED NOT NULL,
  id_solicitacao INT UNSIGNED NULL,
  descricao VARCHAR(255) NOT NULL,
  categoria VARCHAR(30) NOT NULL,
  valor_original DECIMAL(12,2) NOT NULL,
  data_emissao DATE NOT NULL,
  data_vencimento DATE NOT NULL,
  status VARCHAR(15) NOT NULL DEFAULT 'ABERTA',
  CONSTRAINT pk_conta_pagar PRIMARY KEY (id_conta_pagar),
  CONSTRAINT ck_conta_pagar_valor CHECK (valor_original>=0),
  CONSTRAINT ck_conta_pagar_datas CHECK (data_vencimento>=data_emissao),
  CONSTRAINT ck_conta_pagar_status CHECK (status IN ('ABERTA','PARCIAL','PAGA','VENCIDA','CANCELADA')),
  CONSTRAINT fk_conta_pagar_fornecedor FOREIGN KEY (id_fornecedor) REFERENCES fornecedor(id_fornecedor) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_conta_pagar_solicitacao FOREIGN KEY (id_solicitacao) REFERENCES solicitacao_compra(id_solicitacao) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE pagamento_despesa (
  id_pagamento_despesa INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_conta_pagar INT UNSIGNED NOT NULL,
  id_funcionario INT UNSIGNED NOT NULL,
  data_pagamento DATE NOT NULL,
  valor_pago DECIMAL(12,2) NOT NULL,
  forma_pagamento VARCHAR(20) NOT NULL,
  status VARCHAR(15) NOT NULL DEFAULT 'CONFIRMADO',
  CONSTRAINT pk_pagamento_despesa PRIMARY KEY (id_pagamento_despesa),
  CONSTRAINT ck_pgto_despesa_valor CHECK (valor_pago>0),
  CONSTRAINT ck_pgto_despesa_forma CHECK (forma_pagamento IN ('BOLETO','PIX','TRANSFERENCIA','CARTAO','DINHEIRO')),
  CONSTRAINT ck_pgto_despesa_status CHECK (status IN ('PENDENTE','CONFIRMADO','ESTORNADO')),
  CONSTRAINT fk_pgto_despesa_conta FOREIGN KEY (id_conta_pagar) REFERENCES conta_pagar(id_conta_pagar) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_pgto_despesa_funcionario FOREIGN KEY (id_funcionario) REFERENCES funcionario(id_funcionario) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

