-- 4B. Dados complementares para encerramento e renovacao de certificados

UPDATE certificado_digital SET data_aviso_renovacao='2026-07-01', data_solicitacao_renovacao='2026-07-08', status_renovacao='EM_ANDAMENTO' WHERE status='VENCIDO';

UPDATE certificado_digital SET status_renovacao='NAO_INICIADA' WHERE status='ATIVO';

-- Exemplos ficticios de renovacoes concluidas: preserva os certificados
-- antigos e cadastra a nova emissao, sem substituir o historico.
UPDATE certificado_digital
SET status_renovacao='CONCLUIDA'
WHERE id_certificado IN (9,18,27) AND status='VENCIDO';

INSERT INTO certificado_digital
 (id_cliente,tipo,data_emissao,data_validade,status,
  data_aviso_renovacao,data_solicitacao_renovacao,status_renovacao)
VALUES
 (9,'A1','2026-08-03','2027-08-03','ATIVO','2026-07-01','2026-07-08','CONCLUIDA'),
 (18,'A1','2026-08-04','2027-08-04','ATIVO','2026-07-01','2026-07-08','CONCLUIDA'),
 (27,'A1','2026-08-05','2027-08-05','ATIVO','2026-07-01','2026-07-08','CONCLUIDA');


-- Casos ficticios para demonstrar o controle de vencimentos em outubro de 2026.
-- Estes certificados permanecem ativos no retrato de 01/10/2026,
-- ainda sem aviso de renovacao e com validade dentro dos 30 dias seguintes.
UPDATE certificado_digital
SET data_validade = CASE id_certificado
      WHEN 30 THEN '2026-10-12'
      WHEN 40 THEN '2026-10-21'
      WHEN 50 THEN '2026-10-29'
    END,
    status = 'ATIVO',
    data_aviso_renovacao = NULL,
    data_solicitacao_renovacao = NULL,
    status_renovacao = 'NAO_INICIADA'
WHERE id_certificado IN (30, 40, 50);


UPDATE contrato SET motivo_encerramento='Rescisao solicitada pelo cliente', solicitante_encerramento='CLIENTE', data_solicitacao_encerramento=DATE_SUB(data_encerramento,INTERVAL 7 DAY), data_entrega_documentacao=DATE_ADD(data_encerramento,INTERVAL 2 DAY), meio_entrega_documentacao='EMAIL' WHERE status='ENCERRADO';

