-- =====================================================================
-- 5. SELECT COM JOIN: demonstracao de relacionamentos
-- =====================================================================
-- J01 — Clientes, contratos e servicos
SELECT c.codigo_cliente, c.nome_razao_social, s.nome AS servico, cs.valor_acordado
FROM cliente c JOIN contrato ct ON ct.id_cliente=c.id_cliente
JOIN contrato_servico cs ON cs.id_contrato=ct.id_contrato
JOIN servico s ON s.id_servico=cs.id_servico ORDER BY c.id_cliente LIMIT 25;

-- J02 — Tarefas e funcionarios responsaveis
SELECT t.id_tarefa, t.descricao, f.nome AS funcionario, d.nome AS departamento
FROM tarefa t JOIN tarefa_funcionario tf ON tf.id_tarefa=t.id_tarefa
JOIN funcionario f ON f.id_funcionario=tf.id_funcionario
JOIN departamento d ON d.id_departamento=f.id_departamento ORDER BY t.id_tarefa LIMIT 25;

-- J03 — Documentos, tipos e clientes
SELECT c.nome_razao_social, td.nome AS tipo_documento, doc.competencia, doc.status
FROM documento doc JOIN cliente c ON c.id_cliente=doc.id_cliente
JOIN tipo_documento td ON td.id_tipo_documento=doc.id_tipo_documento LIMIT 25;

-- J04 — Compras aprovadas, solicitantes e aprovador
SELECT sc.id_solicitacao, fs.nome AS solicitante, fa.nome AS aprovador, sc.status
FROM solicitacao_compra sc JOIN funcionario fs ON fs.id_funcionario=sc.id_funcionario
LEFT JOIN funcionario fa ON fa.id_funcionario=sc.id_aprovador
ORDER BY sc.id_solicitacao LIMIT 25;

-- J05 — Fornecedores, contas a pagar e pagamentos realizados
SELECT f.nome_razao_social, cp.id_conta_pagar, cp.valor_original,
 pd.valor_pago, pd.data_pagamento
FROM conta_pagar cp JOIN fornecedor f ON f.id_fornecedor=cp.id_fornecedor
LEFT JOIN pagamento_despesa pd ON pd.id_conta_pagar=cp.id_conta_pagar
ORDER BY cp.id_conta_pagar LIMIT 25;

-- =====================================================================
-- 6. UPDATE E DELETE: demonstracoes seguras em transacao
-- ROLLBACK preserva a massa de dados e evita alterar indicadores.
-- =====================================================================
START TRANSACTION;
UPDATE cliente SET status='SUSPENSO' WHERE id_cliente=1;
SELECT id_cliente, status FROM cliente WHERE id_cliente=1;
ROLLBACK;

START TRANSACTION;
INSERT INTO contato (id_cliente,tipo,valor,principal)
VALUES (1,'EMAIL','temporario-teste@exemplo.invalid',0);
SET @contato_teste_id = LAST_INSERT_ID();
DELETE FROM contato WHERE id_contato=@contato_teste_id;
SELECT COUNT(*) AS contato_teste_restante FROM contato WHERE id_contato=@contato_teste_id;
ROLLBACK;

-- =====================================================================
-- 7. CONSULTAS GERENCIAIS (Gxx)
-- Os codigos P01-P05 sao PROPOSTOS e devem coincidir com o README final.
-- KPIs: formule, periodo e meta devem ser documentados na secao 1.6.
-- =====================================================================
-- G01 — Quantos documentos foram recebidos e conferidos por competencia?
-- Atende: P01 (ausencia de registro formal de recebimento); KPI: taxa de conferencia mensal.
SELECT competencia, COUNT(*) AS recebidos,
 SUM(CASE WHEN status='CONFERIDO' THEN 1 ELSE 0 END) AS conferidos,
 ROUND(100.0*SUM(CASE WHEN status='CONFERIDO' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS taxa_conferencia_pct
FROM documento WHERE competencia IS NOT NULL GROUP BY competencia ORDER BY competencia;

-- G02 — Quantas tarefas estao atrasadas por departamento em 2026-10-31?
-- Atende: P02 (controle setorial de tarefas); KPI: tarefas atrasadas por setor.
-- Data de referencia fixa para permitir reproducao do teste.
SELECT d.nome AS departamento, COUNT(DISTINCT t.id_tarefa) AS tarefas_atrasadas
FROM tarefa t JOIN tarefa_funcionario tf ON tf.id_tarefa=t.id_tarefa
JOIN funcionario f ON f.id_funcionario=tf.id_funcionario
JOIN departamento d ON d.id_departamento=f.id_departamento
WHERE t.prazo < '2026-10-31' AND t.data_conclusao IS NULL AND t.status <> 'CANCELADA'
GROUP BY d.id_departamento,d.nome ORDER BY tarefas_atrasadas DESC;

-- G03 — Quais obrigacoes estao pendentes e vencidas em 2026-10-31?
-- Atende: P03 (prazos nao centralizados); KPI: obrigacoes vencidas por competencia.
SELECT o.competencia, COUNT(*) AS obrigacoes_vencidas
FROM obrigacao o WHERE o.prazo < '2026-10-31' AND o.data_conclusao IS NULL
AND o.status <> 'CANCELADA' GROUP BY o.competencia ORDER BY o.competencia;

-- G04 — Quantas obrigacoes ainda nao concluidas vencem nos proximos 15 dias a partir de 2026-10-15?
-- Atende: P03 (ausencia de alertas); KPI: quantidade de obrigacoes a vencer em 15 dias.
-- Periodo: 2026-10-15 a 2026-10-30 (inclusivo); corte fixo para reproducibilidade.
SELECT COUNT(*) AS obrigacoes_a_vencer_15_dias
FROM obrigacao o
WHERE o.data_conclusao IS NULL
  AND o.status <> 'CANCELADA'
  AND o.prazo BETWEEN '2026-10-15' AND DATE_ADD('2026-10-15', INTERVAL 15 DAY);

-- G05 — Quantas pendencias documentais existem por tipo e competencia?
-- Atende: P04 (retrabalho por dados ausentes/incorretos); KPI: pendencias por tipo.
SELECT competencia, tipo_pendencia, COUNT(*) AS total
FROM pendencia_documental WHERE status IN ('ABERTA','COMUNICADA')
GROUP BY competencia,tipo_pendencia ORDER BY competencia,tipo_pendencia;

-- G06 — Qual o faturamento emitido por competencia?
-- Atende: P05 (consolidacao de controles de faturamento); KPI: faturamento emitido mensal.
SELECT competencia, SUM(valor_total) AS faturamento_emitido
FROM fatura WHERE status <> 'CANCELADA' GROUP BY competencia ORDER BY competencia;

-- G07 — Quanto foi recebido e qual saldo em aberto por competencia?
-- Atende: P05 (conferencia de cobrancas); KPI: valor recebido e saldo aberto mensal.
SELECT f.competencia, SUM(f.valor_total) AS total_faturado,
 SUM(COALESCE(p.total_pago,0)) AS total_recebido,
 SUM(GREATEST(f.valor_total-COALESCE(p.total_pago,0),0)) AS saldo_aberto
FROM fatura f LEFT JOIN
 (SELECT id_fatura,SUM(valor_pago) AS total_pago FROM pagamento
  WHERE status='CONFIRMADO' GROUP BY id_fatura) p ON p.id_fatura=f.id_fatura
WHERE f.status <> 'CANCELADA' GROUP BY f.competencia ORDER BY f.competencia;

-- G08 — Quais clientes concentram pendencias documentais?
-- Atende: P04 (reenvios e correcoes); KPI: clientes com mais pendencias.
SELECT c.codigo_cliente,c.nome_razao_social,COUNT(*) AS pendencias
FROM pendencia_documental pd JOIN execucao_servico e ON e.id_execucao=pd.id_execucao
JOIN contrato ct ON ct.id_contrato=e.id_contrato JOIN cliente c ON c.id_cliente=ct.id_cliente
WHERE pd.status IN ('ABERTA','COMUNICADA')
GROUP BY c.id_cliente,c.codigo_cliente,c.nome_razao_social ORDER BY pendencias DESC LIMIT 20;

-- G09 — Qual o total de despesas registradas por mes e categoria?
-- Atende: novo processo de compras/contas a pagar; KPI: despesas mensais por categoria.
SELECT DATE_FORMAT(data_emissao,'%Y-%m') AS competencia, categoria,
 COUNT(*) AS contas, SUM(valor_original) AS despesas_emitidas
FROM conta_pagar WHERE status<>'CANCELADA'
GROUP BY DATE_FORMAT(data_emissao,'%Y-%m'), categoria
ORDER BY competencia,categoria;

-- G10 — Qual o saldo vencido em contas a pagar por fornecedor em 2026-10-31?
-- Atende: controle de contas a pagar; KPI: saldo vencido por fornecedor na data de referencia.
-- Pagamentos confirmados posteriores a 2026-10-31 nao reduzem o saldo historico.
SELECT f.id_fornecedor, f.nome_razao_social,
       COUNT(*) AS contas_vencidas_com_saldo,
       SUM(cp.valor_original - COALESCE(p.total_pago, 0)) AS saldo_vencido
FROM conta_pagar cp
JOIN fornecedor f ON f.id_fornecedor = cp.id_fornecedor
LEFT JOIN (
  SELECT id_conta_pagar, SUM(valor_pago) AS total_pago
  FROM pagamento_despesa
  WHERE status = 'CONFIRMADO' AND data_pagamento <= '2026-10-31'
  GROUP BY id_conta_pagar
) p ON p.id_conta_pagar = cp.id_conta_pagar
WHERE cp.status <> 'CANCELADA'
  AND cp.data_vencimento <= '2026-10-31'
  AND cp.valor_original > COALESCE(p.total_pago, 0)
GROUP BY f.id_fornecedor, f.nome_razao_social
ORDER BY saldo_vencido DESC, f.nome_razao_social;

-- G11 — Qual a taxa de aprovacao das solicitacoes por mes?
-- Atende: acompanhamento da autorizacao de compras; KPI: porcentagem aprovada mensal.
SELECT DATE_FORMAT(data_solicitacao,'%Y-%m') AS competencia,COUNT(*) AS solicitacoes,
 SUM(status='APROVADA') AS aprovadas,
 ROUND(100*SUM(status='APROVADA')/COUNT(*),2) AS taxa_aprovacao_percentual
FROM solicitacao_compra GROUP BY DATE_FORMAT(data_solicitacao,'%Y-%m') ORDER BY competencia;

-- G12 — Quantos certificados ativos sem aviso vencem nos 30 dias seguintes a 2026-10-01?
-- Atende: controle preventivo de renovacao; KPI: certificados proximos do vencimento sem comunicacao.
-- Janela: 2026-10-01 a 2026-10-31 (inclusivo).
SELECT COUNT(*) AS certificados_a_vencer_sem_aviso
FROM certificado_digital cd
WHERE cd.data_validade BETWEEN '2026-10-01' AND DATE_ADD('2026-10-01', INTERVAL 30 DAY)
  AND cd.status = 'ATIVO'
  AND cd.data_aviso_renovacao IS NULL;

-- =====================================================================
-- 8. CONSULTAS DE AUDITORIA (Axx)
-- Resultado vazio significa que nenhuma violacao foi detectada no conjunto.
-- Algumas regras dependem da aplicacao e nao apenas de CHECK/FK.
-- =====================================================================
-- A01 — Existem clientes com codigo interno duplicado?
-- Verifica: RN02 (codigo de identificacao unico).
SELECT codigo_cliente,COUNT(*) AS repeticoes FROM cliente
GROUP BY codigo_cliente HAVING COUNT(*)>1;

-- A02 — Existem clientes sem nenhum responsavel ativo?
-- Verifica: RN05 (cliente deve possuir ao menos um responsavel).
SELECT c.id_cliente,c.nome_razao_social FROM cliente c
LEFT JOIN responsabilidade r ON r.id_cliente=c.id_cliente
AND r.data_inicio<='2026-10-31' AND (r.data_fim IS NULL OR r.data_fim>='2026-10-31')
WHERE r.id_cliente IS NULL;

-- A03 — Existem tarefas sem funcionario designado?
-- Verifica: RN07 (toda tarefa tem ao menos um responsavel).
SELECT t.id_tarefa,t.descricao FROM tarefa t
LEFT JOIN tarefa_funcionario tf ON tf.id_tarefa=t.id_tarefa
WHERE tf.id_tarefa IS NULL;

-- A04 — Ha tarefa iniciada antes da conclusao de pre-requisito?
-- Verifica: RN08 (dependencia entre tarefas).
SELECT t.id_tarefa AS tarefa_dependente,pre.id_tarefa AS pre_requisito,
 t.data_inicio AS inicio_dependente,pre.data_conclusao AS conclusao_pre_requisito
FROM tarefa_dependencia dep
JOIN tarefa t ON t.id_tarefa=dep.id_tarefa_dependente
JOIN tarefa pre ON pre.id_tarefa=dep.id_tarefa_pre_requisito
WHERE t.data_inicio IS NOT NULL AND
 (pre.data_conclusao IS NULL OR t.data_inicio<pre.data_conclusao);

-- A05 — Ha execucao concluida sem revisao aprovada?
-- Verifica: RN09 (revisao obrigatoria antes da conclusao).
SELECT e.id_execucao FROM execucao_servico e
WHERE e.status='CONCLUIDA' AND NOT EXISTS
 (SELECT 1 FROM revisao_execucao r WHERE r.id_execucao=e.id_execucao
  AND r.resultado IN ('APROVADA','APROVADA_COM_RESSALVAS')
  AND r.data_revisao<=e.data_conclusao);

-- A06 — Ha obrigacao entregue sem revisao aprovada?
-- Verifica: RN09 (revisao obrigatoria de obrigacoes).
SELECT o.id_obrigacao FROM obrigacao o
WHERE o.status='ENTREGUE' AND NOT EXISTS
 (SELECT 1 FROM revisao_obrigacao r WHERE r.id_obrigacao=o.id_obrigacao
  AND r.resultado IN ('APROVADA','APROVADA_COM_RESSALVAS')
  AND r.data_revisao<=o.data_conclusao);

-- A07 — Existem pagamentos confirmados por meio diferente de boleto?
-- Verifica: RN14 (cobranca quitada exclusivamente por boleto).
SELECT id_pagamento,id_fatura,forma_pagamento FROM pagamento
WHERE status='CONFIRMADO' AND forma_pagamento<>'BOLETO';

-- A08 — Existem contratos encerrados sem destino documental registrado?
-- Verifica: RN16 (destino da documentacao no encerramento).
SELECT id_contrato,id_cliente FROM contrato
WHERE status='ENCERRADO' AND
 (destino_documentacao IS NULL OR TRIM(destino_documentacao)='');

-- A09 — Ha responsabilidade vinculada a departamento diferente da lotacao?
-- Verifica: RN06/RN05 (lotacao unica e responsabilidade coerente).
SELECT r.id_cliente,r.id_funcionario,r.id_departamento AS departamento_atribuido,
 f.id_departamento AS departamento_funcionario
FROM responsabilidade r JOIN funcionario f ON f.id_funcionario=r.id_funcionario
WHERE r.id_departamento<>f.id_departamento;

-- A10 — Existem execucoes de servicos nao incluidos no contrato?
-- Verifica: RN04 (servicos contratados vinculados a seus contratos).
SELECT e.id_execucao,e.id_contrato,e.id_servico FROM execucao_servico e
LEFT JOIN contrato_servico cs ON cs.id_contrato=e.id_contrato AND cs.id_servico=e.id_servico
WHERE cs.id_contrato IS NULL;

-- A11 — Ha documentos associados a execucoes de outros clientes?
-- Verifica: RN01/RN10 (documentacao vinculada ao cliente correto).
SELECT ed.id_execucao,ed.id_documento,d.id_cliente AS cliente_documento,
 ct.id_cliente AS cliente_execucao FROM execucao_documento ed
JOIN documento d ON d.id_documento=ed.id_documento
JOIN execucao_servico e ON e.id_execucao=ed.id_execucao
JOIN contrato ct ON ct.id_contrato=e.id_contrato
WHERE d.id_cliente<>ct.id_cliente;

-- A12 — Existem faturas pagas sem valor confirmado suficiente?
-- Verifica: RN14 (quitacao de fatura por pagamento confirmado).
SELECT f.id_fatura,f.valor_total,COALESCE(SUM(p.valor_pago),0) AS valor_confirmado
FROM fatura f LEFT JOIN pagamento p ON p.id_fatura=f.id_fatura AND p.status='CONFIRMADO'
WHERE f.status='PAGA' GROUP BY f.id_fatura,f.valor_total
HAVING COALESCE(SUM(p.valor_pago),0)<f.valor_total;

-- A13 — Existem compras aprovadas sem identificacao do aprovador ou data da decisao?
-- Verifica: regra revisada de autorizacao de compras pelo proprietario.
SELECT id_solicitacao,status FROM solicitacao_compra
WHERE status='APROVADA' AND (id_aprovador IS NULL OR data_decisao IS NULL);

-- A14 — Existem contas a pagar relacionadas a solicitacoes nao aprovadas?
-- Verifica: solicitacoes de compra devem ser aprovadas antes de originar cobranca.
SELECT cp.id_conta_pagar,cp.id_solicitacao,sc.status
FROM conta_pagar cp JOIN solicitacao_compra sc ON sc.id_solicitacao=cp.id_solicitacao
WHERE sc.status<>'APROVADA';

-- A15 — Existe conta paga com valor confirmado insuficiente ou excessivo?
-- Verifica: conciliacao dos pagamentos de despesas com o valor da conta.
SELECT cp.id_conta_pagar,cp.valor_original,COALESCE(SUM(pd.valor_pago),0) AS recebido
FROM conta_pagar cp LEFT JOIN pagamento_despesa pd ON pd.id_conta_pagar=cp.id_conta_pagar
AND pd.status='CONFIRMADO' GROUP BY cp.id_conta_pagar,cp.valor_original,cp.status
HAVING (cp.status='PAGA' AND ABS(cp.valor_original-COALESCE(SUM(pd.valor_pago),0))>0.005)
OR COALESCE(SUM(pd.valor_pago),0)>cp.valor_original;

-- A16 — Existem compras aprovadas sem responsavel cadastrado como proprietario/diretor?
-- Verifica: regra informada na entrevista sobre autorizacao pelo proprietario.
-- A verificacao utiliza cargo em vez de ID fixo, pois a massa de dados e ilustrativa.
-- Em producao, permissoes de aprovacao devem ser modeladas explicitamente.
SELECT sc.id_solicitacao,sc.id_aprovador, f.cargo AS cargo_aprovador
FROM solicitacao_compra sc
LEFT JOIN funcionario f ON f.id_funcionario=sc.id_aprovador
WHERE sc.status='APROVADA'
AND (f.id_funcionario IS NULL OR f.cargo <> 'Proprietario e diretor');

-- =====================================================================
-- 9. CONTAGENS PARA CONFERENCIA DA MASSA DE DADOS
-- =====================================================================
SELECT 'cliente' AS tabela, COUNT(*) AS registros FROM cliente
UNION ALL SELECT 'funcionario',COUNT(*) FROM funcionario
UNION ALL SELECT 'contrato',COUNT(*) FROM contrato
UNION ALL SELECT 'fatura',COUNT(*) FROM fatura
UNION ALL SELECT 'pagamento',COUNT(*) FROM pagamento
UNION ALL SELECT 'execucao_servico',COUNT(*) FROM execucao_servico
UNION ALL SELECT 'tarefa',COUNT(*) FROM tarefa
UNION ALL SELECT 'obrigacao',COUNT(*) FROM obrigacao
UNION ALL SELECT 'documento',COUNT(*) FROM documento
UNION ALL SELECT 'pendencia_documental',COUNT(*) FROM pendencia_documental
UNION ALL SELECT 'fornecedor',COUNT(*) FROM fornecedor
UNION ALL SELECT 'solicitacao_compra',COUNT(*) FROM solicitacao_compra
UNION ALL SELECT 'item_compra',COUNT(*) FROM item_compra
UNION ALL SELECT 'conta_pagar',COUNT(*) FROM conta_pagar
UNION ALL SELECT 'pagamento_despesa',COUNT(*) FROM pagamento_despesa;
